/**
 * Cross-language pin: the quantities the game and the product both compute
 * must agree, because the submission claims they do.
 *
 * The fixture is generated by `game/scripts/vectors_from_product.py` from
 * `src/services/rates.py` — the product's own statutory-interest module — so
 * this is not the game checking itself. It covers both base rates in play:
 * the game's labelled input (3.75% since 18 Dec 2025) and the product's env
 * default (5.25%), and it includes the £1,000 / £10,000 band boundaries where
 * an off-by-one is invisible in play and wrong on a letter to a debtor.
 */
import { describe, expect, it } from "vitest";
import { statutoryInterest, statutoryCompensation, statutoryRatePct, DEFAULT_BASE_RATE_PCT } from "../src/engine/rates";
import { productCheckUrl, PRODUCT_URL, PRODUCT_CHECK_SECTOR } from "../src/engine/links";
import fixture from "./fixtures/product-vectors.json";

interface Vector {
  base_rate_pct: number;
  apr_pct: number;
  principal: number;
  days_late: number;
  interest: number;
  compensation: number;
}

const vectors = fixture.rows as Vector[];

describe("product vectors — shared statutory quantities", () => {
  it("pins the game's shipped base rate to the product's arithmetic", () => {
    expect(statutoryRatePct()).toBe(fixture.product_apr_at_game_base_pct);
    // The game's labelled base rate is the one the fixture was built at.
    expect(DEFAULT_BASE_RATE_PCT).toBe(3.75);
  });

  it("reproduces the product's interest to the penny across 96 vectors", () => {
    for (const v of vectors) {
      const apr = statutoryRatePct(v.base_rate_pct);
      expect(apr).toBe(v.apr_pct); // same 8-point margin, no drift in the margin itself
      const ours = statutoryInterest(v.principal, v.days_late, v.base_rate_pct);
      // Interest is displayed rounded; the arithmetic must agree far below a penny.
      expect(Math.abs(ours - v.interest)).toBeLessThan(0.005);
    }
  });

  it("agrees on the compensation bands, including the boundaries", () => {
    for (const v of vectors) {
      expect(statutoryCompensation(v.principal)).toBe(v.compensation);
    }
    // Explicit, because these are the two values a boundary bug hides behind.
    expect(statutoryCompensation(1000)).toBe(40);
    expect(statutoryCompensation(1000.01)).toBe(70);
    expect(statutoryCompensation(10000)).toBe(70);
    expect(statutoryCompensation(10000.01)).toBe(100);
  });
});

describe("the door out of the finale", () => {
  it("points at the read-only check on the live product, never at a wall", () => {
    const url = new URL(productCheckUrl());
    expect(url.origin).toBe(PRODUCT_URL);
    expect(url.pathname).toBe(`/check/${PRODUCT_CHECK_SECTOR}`);
    expect(url.protocol).toBe("https:");
    expect(url.searchParams.get("utm_source")).toBe("late_market");
    expect(url.searchParams.get("utm_medium")).toBe("game");
    expect(url.searchParams.get("utm_campaign")).toBe("zoud");
  });

  it("encodes a sector rather than letting it break the path", () => {
    expect(productCheckUrl("a b/c")).toContain("/check/a%20b%2Fc?");
  });
});
